-- Forever-specific quick guide. Loaded after the general UI strings so older
-- Retail guide text cannot reappear when a locale falls back to English.
local L = Overlord.L
local locale = GetLocale() or "enUS"
local lang = ({ frFR = "fr", esES = "es", esMX = "es", deDE = "de",
    ruRU = "ru", ptBR = "pt", zhCN = "zhCN", zhTW = "zhCN" })[locale] or "en"

-- GUIDE_GUILD_KEEP_BODY : %s = icon legend, %d = hold minutes (Popups.lua).
-- GUIDE_GOLD_BODY : %s = mine list (Popups.lua).
local guide = {
en = {
    GUIDE_BTN_TOOLTIP = "Forever guide (3 pages)",
    GUIDE_PAGE1_TITLE = "Getting started", GUIDE_PAGE2_TITLE = "Captures and resources",
    GUIDE_PAGE3_TITLE = "Keeps, outposts and rankings",
    GUIDE_SECTION_TRAVEL = "Enter the open world",
    GUIDE_TRAVEL_ALLIANCE = "- Go to an Overlord war front in the open world.\n- The map shows the points you can capture; the panel's Next Objective shows the way.\n- On the world map, a large emblem over each continent shows the faction that dominates the most fronts there.",
    GUIDE_SECTION_RULES = "Before you capture",
    GUIDE_RULES_BODY = "- Turn on PvP (/pvp) and stand on foot inside the circle.\n- Capturing pauses while mounted, flying, in travel form, in a vehicle or on a taxi, stealthed or dead.\n- Flying into a circle dismounts you after a short warning.",
    GUIDE_SECTION_PROGRESS = "The seven war fronts",
    GUIDE_PROGRESS_BODY = "- Arathi Highlands, Loch Modan, Durotar, Ashenvale, Elwynn Forest, Redridge Mountains and Hillsbrad Foothills: a capture path between two faction capitals.\n- A point opens once the points before it are yours; several branches can be open at once. Open points show in yellow with crossed swords.\n- Open-world honorable kills (HK) count once at any level, from Blizzard's official counter.",
    GUIDE_SECTION_SHARD = "Layers and synchronization",
    GUIDE_SHARD_BODY = "- Captures and rankings are shared with every player of your realm type (PvP, Normal, RP, RP-PvP or Hardcore): addon channel, guild, group and Battle.net friends.\n- If the game refuses the addon channel or nobody answers on it, data goes through your guild instead (/ov guild off to stop it). Overlord also exchanges data, by invisible whispers, with a few players from the channel's member list, whatever their guild: captures, sieges, fights (Recent activity) and guild rampages are passed from hand to hand within seconds, maps and rankings keep crossing guilds, even without one. Players met this way are found again later, even when the game hides the member list.\n- The ranking fills in by itself in the background, even with its window closed.\n- The dot in the panel header shows the network health, green as long as the channel, its member list or your guild carries your data (a refused channel included); /ov network gives details.\n- A layer is your copy of the open world: group up to fight beside allies on another layer.\n- Layers: click the Layers button of the panel, or the layer number at its top left, to list the players Overlord hears and their layers. Join asks a volunteer on that layer for an invite; you leave the group by yourself once moved. Volunteers only: Help others is off by default. Volunteers show a portal icon in the list and are asked first; a refusal says why.",
    GUIDE_SECTION_PANEL = "The Overlord panel",
    GUIDE_PANEL_BODY = "- Minimap button or /ov show (/ov alone lists the commands).\n- Pick a front: its points, the current capture, recent fighting and the weekly domination bar (hover it: this week's front victories).\n- Buttons: PvP Groups, Call to arms, Command, the leaderboard and the Hall of Fame.\n- Your platinum, Attack and Reinforce sit in the Next Objective card.\n- Reopen this guide from the panel or with /ov guide.",
    GUIDE_SECTION_OPTIONS = "Settings and commands",
    GUIDE_OPTIONS_BODY = "- In the panel, or Escape → Options → AddOns → Overlord.\n- Objective pin, world map, Minimap icons, sounds, panel scale, floating panel, Nemesis and guild alerts.\n- Handy commands: /ov lb (leaderboard), /ov map (world map: full, compact, circles only or hidden, also with the Overlord button in the map's corner: right-click + drag moves it, /ov map button hides it), /ov sync (catch up), /ov guildkills.",
    GUIDE_SECTION_CONTEST = "Capture and contest",
    GUIDE_CONTEST_BODY = "- Normal circle: stay 2 minutes; leaving makes the progress fall back.\n- As many enemies as you, or more, push it back, faster the more they outnumber you.\n- Enemy capital: 8 minutes. Retaking your own: 2 minutes.\n- A point exists on every layer: an attacker on another layer cannot be seen or stopped from yours. The chat tells you; join their layer to fight.\n- A capture waits, on hold, while a point it needs is attacked after it began.\n- One timer per point: when several of you stand on it, the capture that began first counts and the others follow it. If its capturer leaves the point or dies, a member of the group standing on it carries the capture on.",
    GUIDE_SECTION_SIEGE = "Capital victory",
    GUIDE_SIEGE_BODY = "- Once every other point of the front is yours, assault the enemy capital.\n- Taking it wins the front: +1% weekly domination and a 15-minute truce.\n- After the truce your conquest stays, the fallen capital included, until its faction retakes it (a faction can always attack its own capital).\n- A new victory on the same front only counts 6 hours after the previous one.",
    GUIDE_SIEGE_BODY_NOTRUCE = "- Once every other point of the front is yours, assault the enemy capital.\n- Taking it wins the front: +1% weekly domination.\n- Your conquest stays, the fallen capital included, until its faction retakes it (a faction can always attack its own capital).\n- A new victory on the same front only counts 6 hours after the previous one.",
    GUIDE_SECTION_GOLD = "Platinum mines",
    GUIDE_GOLD_BODY = "Mines on the map:\n%s\n\n- In a mine circle, PvP on (/pvp): 1 platinum every 3 seconds (personal cap 100); an ore node gives 5.\n- Attack, 25 platinum: your next capture is 60 seconds shorter (not capitals).\n- Reinforce, 25 platinum: the next enemy capture of one of your points takes 60 seconds more (not capitals).\n- The shared mine stock refills over time.",
    GUIDE_SECTION_FEATURED = "Featured front and weekly reset",
    GUIDE_FEATURED_BODY = "- The featured front changes every day at midnight, your local time.\n- Each official HK on it gives +1 Overlord platinum.\n- Rankings, domination and the war map reset every week, on your region's schedule (Americas: Tuesday, Europe: Wednesday, Korea and Taiwan: Thursday morning).",
    GUIDE_SECTION_GUILD_KEEP = "Guild Keeps",
    GUIDE_GUILD_KEEP_BODY = "Five keeps: Stonetalon Mountains, Wetlands, Badlands, the Barrens and Mulgore.\n%s\n\n- Open at all times: a guild member holds the square for %d minutes.\n- Leaving makes the progress fall back; equal enemy numbers freeze it, more enemies push it back.\n- Only the opposing faction can contest or take it.\n- It stays with its guild until an enemy capture or the weekly reset; the leaderboard's keeps table counts the captures and its tooltip names who took it.\n- The scroll icon in the leaderboard's outposts header shows this week's top capturers and guild rivalries.",
    GUIDE_SECTION_OUTPOST = "Guild outposts",
    GUIDE_OUTPOST_BODY = "- One per front, plus Savix Chapel (Silverpine Forest), Aeythyr Lodge (Eastern Plaguelands), Lesi's Bear Cave (Darkshore) and Anad'Ora Moonwell (Feralas).\n- Keep rules, but 5 minutes.\n- While a guild of your faction holds a front's outpost, the enemy needs 30 more seconds on that front's ordinary points.",
    GUIDE_SECTION_FACTION_CALL = "Call to arms and General",
    GUIDE_FACTION_CALL_BODY = "- Call to arms: on an active front, the button opens a horn; a click on the horn sends a raid warning to every Overlord ally of your faction (once every 4 hours for the whole faction).\n- Command: a party or raid leader becomes the faction's General, shown on the map, the minimap and their nameplate; everyone is told when the General falls.",
    GUIDE_SECTION_ALERTS = "Alerts",
    GUIDE_ALERTS_BODY = "- Nemesis: the week's five best enemy killers wear a skull on their nameplate, and the chat warns you when one shows up (on or off in the options). Your killing blow on one of them earns +10 platinum (once per player per half hour).\n- Enemy rampage: an enemy guild racks up HK in a short time (/ov guildkills on or off).\n- Allied rampage, in green: a guild of your faction does it (/ov guildkills allies on or off).\n- Capture, outpost and mine alerts come from the zone you are in: \"Capture alerts\" in the options widens them to your continent or the whole world. Your guild's keeps and outposts, rampages, calls to arms and total victories always reach you. Keeps and outposts of other guilds stay silent unless you tick \"Keep and outpost alerts of other guilds\".\n- Big battles: a chat line when a fight reaches 50 kills or more in 5 minutes, anywhere in the world (\"Big battle alerts\" in the options).",
    GUIDE_SECTION_GROUPS = "PvP groups",
    GUIDE_GROUPS_BODY = "- PvP Groups (panel button or /ov groups): publish your group with an objective, a place, a size and a minimum level, or sign up to a listed one.\n- Listings reach the Overlord players of your faction. The leader invites you, automatically or after approving your request; you accept the game's invitation yourself.\n- You can join a group every 2 minutes. Off in instances.",
    GUIDE_SECTION_TOOLS = "Rankings and Hall of Fame",
    GUIDE_TOOLS_BODY = "- Weekly leaderboard (/ov lb): HK, guilds with their ranked members (click a guild to list them all), the guild rating (HK and captures; click HK or Rating to sort the guilds), keeps and outposts, a search box, the time left and your rank; in the header, between the totals and your rank, a green arrow while ranking data is still arriving, then a green check once it is up to date.\n- /ov sync asks reachable players for a catch-up.\n- Hall of Fame (panel button): last week's champions, your feats and the donors.",
    GUIDE_SECTION_RANKS = "Overlord Rank",
    GUIDE_RANKS_BODY = "- A new tab on your character sheet (Overlord logo): fifteen ranks; a rank earned never drops.\n- Ranks 1 to 10 are earned with Glory: every open-world honorable kill counts, and a capture counts more. Only what Overlord sees from now on counts.\n- Ranks 11 to 14 also ask for three weeks finished in the top 100, 25, 10 then 3 of your faction's weekly ranking; the last one, Overlord, asks for more Glory and five weeks finished first in your faction (at least 1,000 honorable kills in each). Weeks add up and need not follow each other; a better week also counts for the wider tops. A week counts from 100 honorable kills, if you played during its last 24 hours. A top 3 week or a week finished first also requires that your ranking was compared with other players during those 24 hours.\n- Your rank is saved only on this computer, for this character, with no copy anywhere else: if the game's addon data is deleted or lost (game reinstalled, disk changed, another computer), the rank starts again from zero and cannot be restored.\n- From rank 11, other players see its badge next to your name, in the ranking and on nameplates, once their own client has checked it: players of your faction against the game's data and their own weekly rankings (once they have met you on different weeks), players of the other faction against their own weekly rankings. A player who missed your best weeks may see it later, or not at all.\n- Each rank reached is announced on screen and listed in the Hall of Fame, under Your feats.",
    -- 2.1.1: /ov guild.
    HELP_GUILD_LANE = "|cFFFFFF00/ov guild [on || off]|r: Network messages in your guild when the game refuses the addon channel or nobody answers on it",
    GUILD_LANE_ON = "Network messages in the guild when the addon channel is refused or silent: on (/ov guild off to stop them).",
    REPORT_WINDOW_TITLE = "Overlord network report",
    REPORT_SELECT_ALL = "Select all (then Ctrl+C)",
    GUILD_LANE_OFF = "Network messages in the guild when the addon channel is refused or silent: off (/ov guild on to allow them). What your guild mates send is still read."
},
fr = {
    GUIDE_BTN_TOOLTIP = "Guide Forever (3 pages)",
    GUIDE_PAGE1_TITLE = "Premiers pas", GUIDE_PAGE2_TITLE = "Captures et ressources",
    GUIDE_PAGE3_TITLE = "Forts, avant-postes et classement",
    GUIDE_SECTION_TRAVEL = "Rejoindre le monde ouvert",
    GUIDE_TRAVEL_ALLIANCE = "- Rendez-vous sur un front Overlord en monde ouvert.\n- La carte montre les points à capturer ; le Prochain objectif du panneau indique le chemin.\n- Sur la carte du monde, un grand blason sur chaque continent montre la faction qui y domine le plus de fronts.",
    GUIDE_SECTION_RULES = "Avant de capturer",
    GUIDE_RULES_BODY = "- Activez le JcJ (/pvp) et restez à pied dans le cercle.\n- La capture s'arrête sur une monture, en vol, en forme de voyage, dans un véhicule ou un taxi, camouflé ou mort.\n- Arriver en vol dans un cercle vous démonte après un court avertissement.",
    GUIDE_SECTION_PROGRESS = "Les sept fronts",
    GUIDE_PROGRESS_BODY = "- Hautes-terres d'Arathi, Loch Modan, Durotar, Orneval, forêt d'Elwynn, Carmines et contreforts de Hautebrande : un parcours de capture entre deux capitales.\n- Un point s'ouvre quand ceux qui le précèdent sont à vous ; plusieurs branches peuvent être ouvertes à la fois. Les points ouverts s'affichent en jaune avec des épées croisées.\n- Les victoires honorables (VH) en monde ouvert comptent une fois à tout niveau, d'après le compteur officiel de Blizzard.",
    GUIDE_SECTION_SHARD = "Layers et synchronisation",
    GUIDE_SHARD_BODY = "- Captures et classement sont partagés avec tous les joueurs de votre type de royaume (JcJ, Normal, JdR, JdR JcJ ou Hardcore) : canal de l'addon, guilde, groupe et amis Battle.net.\n- Si le jeu refuse le canal de l'addon ou que personne n'y répond, les données passent par votre guilde (/ov guild off pour l'arrêter). Overlord échange aussi des données, par chuchotements invisibles, avec quelques joueurs de la liste des membres du canal, quelle que soit leur guilde : captures, sièges, combats (Activité récente) et carnages de guilde passent de main en main en quelques secondes, cartes et classement passent toujours d'une guilde à l'autre, même sans guilde. Les joueurs rencontrés ainsi sont retrouvés ensuite, même quand le jeu cache la liste des membres.\n- Le classement se remplit tout seul en arrière-plan, même fenêtre fermée.\n- Le point dans l'en-tête du panneau montre l'état du réseau, vert tant que le canal, sa liste des membres ou votre guilde transporte vos données (canal refusé compris) ; /ov network donne le détail.\n- Un layer est votre copie du monde ouvert : groupez-vous pour combattre avec des alliés d'un autre layer.\n- Layers : clique sur le bouton Layers du panneau, ou sur le numéro de layer en haut à gauche, pour lister les joueurs qu'Overlord entend et leur layer. Rejoindre demande une invitation à un volontaire de ce layer ; tu quittes le groupe tout seul une fois passé. Volontaires seulement : « Aider les autres » est désactivé par défaut. Les volontaires portent une icône de portail dans la liste et sont sollicités en premier ; un refus dit pourquoi.",
    GUIDE_SECTION_PANEL = "Le panneau Overlord",
    GUIDE_PANEL_BODY = "- Bouton de la minicarte ou /ov show (/ov seul liste les commandes).\n- Choisissez un front : ses points, la capture en cours, les combats récents et la barre de domination de la semaine (survolez-la : victoires de front de la semaine).\n- Boutons : Groupes JcJ, Appel aux armes, Commander, le classement et le Panthéon.\n- Votre platine, Attaquer et Renforcer sont dans la carte Prochain objectif.\n- Rouvrez ce guide depuis le panneau ou avec /ov guide.",
    GUIDE_SECTION_OPTIONS = "Options et commandes",
    GUIDE_OPTIONS_BODY = "- Dans le panneau, ou Échap → Options → AddOns → Overlord.\n- Repère d'objectif, carte du monde, Icônes de la minicarte, sons, échelle du panneau, panneau flottant, Némésis et alertes de guilde.\n- Commandes pratiques : /ov lb (classement), /ov map (carte du monde : complète, compacte, cercles seuls ou masquée, aussi avec le bouton Overlord dans le coin de la carte : clic droit + glisser le déplace, /ov map button le masque), /ov sync (rattrapage), /ov guildkills.",
    GUIDE_SECTION_CONTEST = "Capture et contestation",
    GUIDE_CONTEST_BODY = "- Cercle normal : restez 2 minutes ; si vous sortez, la progression redescend.\n- Des ennemis aussi nombreux que vous ou plus la font reculer, d'autant plus vite qu'ils sont nombreux.\n- Capitale ennemie : 8 minutes. Reprendre la vôtre : 2 minutes.\n- Un point existe sur chaque layer : un attaquant sur un autre layer ne peut être ni vu ni arrêté depuis le vôtre. Le chat vous le dit ; rejoignez son layer pour vous battre.\n- Une capture attend, en pause, tant qu'un point dont elle dépend est attaqué après son début.\n- Un seul minuteur par point : si vous êtes plusieurs dessus, la capture commencée en premier compte et les autres la suivent. Si son capteur quitte le point ou meurt, un membre du groupe présent sur le point poursuit la capture.",
    GUIDE_SECTION_SIEGE = "Victoire sur une capitale",
    GUIDE_SIEGE_BODY = "- Quand tous les autres points du front sont à vous, attaquez la capitale ennemie.\n- Sa prise remporte le front : +1 % de domination hebdomadaire et une trêve de 15 minutes.\n- Après la trêve, la conquête reste, capitale tombée comprise, jusqu'à ce que sa faction la reprenne (une faction peut toujours attaquer sa propre capitale).\n- Une nouvelle victoire sur le même front ne compte que 6 heures après la précédente.",
    GUIDE_SIEGE_BODY_NOTRUCE = "- Quand tous les autres points du front sont à vous, attaquez la capitale ennemie.\n- Sa prise remporte le front : +1 % de domination hebdomadaire.\n- La conquête reste, capitale tombée comprise, jusqu'à ce que sa faction la reprenne (une faction peut toujours attaquer sa propre capitale).\n- Une nouvelle victoire sur le même front ne compte que 6 heures après la précédente.",
    GUIDE_SECTION_GOLD = "Mines de platine",
    GUIDE_GOLD_BODY = "Mines sur la carte :\n%s\n\n- Dans le cercle d'une mine, JcJ activé (/pvp) : 1 platine toutes les 3 secondes (maximum personnel 100) ; une veine minée en donne 5.\n- Attaquer, 25 platine : votre prochaine capture dure 60 secondes de moins (hors capitales).\n- Renforcer, 25 platine : la prochaine capture ennemie d'un de vos points dure 60 secondes de plus (hors capitales).\n- Le stock partagé des mines se régénère.",
    GUIDE_SECTION_FEATURED = "Front du jour et remise à zéro hebdomadaire",
    GUIDE_FEATURED_BODY = "- Le front du jour change chaque jour à minuit, heure de votre PC.\n- Chaque VH officielle sur ce front donne +1 platine.\n- Le classement, la domination et la carte de guerre repartent à zéro chaque semaine, à l'heure de votre région (Amériques : mardi, Europe : mercredi, Corée et Taïwan : jeudi matin).",
    GUIDE_SECTION_GUILD_KEEP = "Forts de guilde",
    GUIDE_GUILD_KEEP_BODY = "Cinq forts : Serres-Rocheuses, Paluns, Terres Ingrates, Tarides et Mulgore.\n%s\n\n- Ouverts à toute heure : un membre de guilde tient le carré %d minutes.\n- Sortir fait redescendre la progression ; autant d'ennemis la figent, davantage la font reculer.\n- Seule la faction adverse peut le contester ou le prendre.\n- Il reste à sa guilde jusqu'à une prise ennemie ou au reset hebdomadaire ; le tableau des forts du classement compte les captures et son infobulle nomme le capteur.\n- L'icône parchemin de l'en-tête des avant-postes du classement affiche les preneurs et les rivalités de guildes de la semaine.",
    GUIDE_SECTION_OUTPOST = "Avant-postes de guilde",
    GUIDE_OUTPOST_BODY = "- Un par front, plus la chapelle de Savix (forêt des Pins-Argentés), le pavillon d'Aeythyr (Maleterres de l'Est), la grotte de l'ours de Lesi (Sombrivage) et le puits de lune d'Anad'Ora (Féralas).\n- Règles des forts, mais 5 minutes.\n- Tant qu'une guilde de votre faction tient l'avant-poste d'un front, l'ennemi met 30 secondes de plus sur les points ordinaires de ce front.",
    GUIDE_SECTION_FACTION_CALL = "Appel aux armes et Général",
    GUIDE_FACTION_CALL_BODY = "- Appel aux armes : sur un front actif, le bouton ouvre un cor ; un clic sur le cor envoie un avertissement de raid à tous les alliés Overlord de votre faction (une fois toutes les 4 heures pour toute la faction).\n- Commander : un chef de groupe ou de raid devient le Général de sa faction, visible sur la carte, la minicarte et sa barre de nom ; tout le monde est prévenu quand il tombe.",
    GUIDE_SECTION_ALERTS = "Alertes",
    GUIDE_ALERTS_BODY = "- Némésis : les cinq meilleurs tueurs ennemis de la semaine portent un crâne sur leur barre de nom, et le chat vous prévient quand l'un d'eux apparaît (activable ou non dans les options). Votre coup fatal sur l'un d'eux rapporte +10 platine (une fois par joueur et par demi-heure).\n- Carnage ennemi : une guilde ennemie enchaîne les VH en peu de temps (/ov guildkills on ou off).\n- Carnage allié, en vert : une guilde de votre faction fait de même (/ov guildkills allies on ou off).\n- Les alertes de capture, d'avant-poste et de mine viennent de la zone où vous êtes : « Alertes de capture » dans les options les étend à votre continent ou au monde entier. Les forts et avant-postes de votre guilde, les carnages, les appels aux armes et les victoires totales vous parviennent toujours. Les forts et avant-postes des autres guildes restent muets, sauf si vous cochez « Alertes des forts et avant-postes des autres guildes ».\n- Grandes batailles : une ligne de chat quand un combat atteint 50 victimes ou plus en 5 minutes, partout dans le monde (« Alertes de grande bataille » dans les options).",
    GUIDE_SECTION_GROUPS = "Groupes JcJ",
    GUIDE_GROUPS_BODY = "- Groupes JcJ (bouton du panneau ou /ov groups) : publiez votre groupe avec un objectif, un lieu, une taille et un niveau minimum, ou inscrivez-vous à un groupe affiché.\n- Les annonces atteignent les joueurs Overlord de votre faction. Le chef vous invite, automatiquement ou après validation de votre demande ; vous acceptez vous-même l'invitation du jeu.\n- Vous pouvez rejoindre un groupe toutes les 2 minutes. Désactivé en instance.",
    GUIDE_SECTION_TOOLS = "Classement et Panthéon",
    GUIDE_TOOLS_BODY = "- Classement de la semaine (/ov lb) : VH, guildes avec leurs membres classés (un clic sur une guilde les liste tous), cote des guildes (VH et captures ; un clic sur VH ou Cote trie les guildes), forts et avant-postes, recherche, temps restant et votre rang ; dans l'en-tête, entre les totaux et votre rang, une flèche verte tant que les données du classement arrivent, puis une coche verte quand il est à jour.\n- /ov sync demande un rattrapage aux joueurs joignables.\n- Panthéon (bouton du panneau) : les champions de la semaine passée, vos exploits et les donateurs.",
    GUIDE_SECTION_RANKS = "Rang Overlord",
    GUIDE_RANKS_BODY = "- Un nouvel onglet sur votre feuille de personnage (logo Overlord) : quinze rangs ; un rang acquis ne redescend pas.\n- Les rangs 1 à 10 se paient en Gloire : chaque victoire honorable en monde ouvert compte, et une capture compte davantage. Seul compte ce qu'Overlord voit à partir de maintenant.\n- Les rangs 11 à 14 demandent aussi trois semaines finies dans le top 100, 25, 10 puis 3 du classement hebdomadaire de votre faction ; le dernier, Overlord, demande davantage de Gloire et cinq semaines finies en tête de votre faction (avec au moins 1 000 victoires honorables chacune). Les semaines s'additionnent sans devoir se suivre ; une meilleure semaine compte aussi pour les tops plus larges. Une semaine compte à partir de 100 victoires honorables, si vous avez joué pendant ses 24 dernières heures. Une semaine dans le top 3 ou finie en tête demande en plus que votre classement ait été comparé à celui d'autres joueurs pendant ces 24 heures.\n- Votre rang est enregistré uniquement sur cet ordinateur, pour ce personnage, sans aucune copie ailleurs : si les données d'addons du jeu sont effacées ou perdues (jeu réinstallé, disque changé, autre ordinateur), le rang repart de zéro et ne peut pas être restauré.\n- À partir du rang 11, les autres joueurs voient son insigne à côté de votre nom, dans le classement et sur les barres de nom, une fois que leur propre client l'a vérifié : ceux de votre faction avec les données du jeu et leurs propres classements hebdomadaires (une fois qu'ils vous ont croisé à des semaines différentes), ceux de l'autre faction avec leurs propres classements hebdomadaires. Un joueur qui a manqué vos meilleures semaines peut le voir plus tard, ou jamais.\n- Chaque rang atteint est annoncé à l'écran et figure au Panthéon, dans Vos exploits.",
    -- 2.1.1: /ov guild.
    HELP_GUILD_LANE = "|cFFFFFF00/ov guild [on || off]|r : messages réseau dans votre guilde quand le jeu refuse le canal de l'addon ou que personne n'y répond",
    GUILD_LANE_ON = "Messages réseau dans la guilde quand le canal de l'addon est refusé ou muet : activés (/ov guild off pour les couper).",
    REPORT_WINDOW_TITLE = "Overlord : rapport réseau",
    REPORT_SELECT_ALL = "Tout sélectionner (puis Ctrl+C)",
    GUILD_LANE_OFF = "Messages réseau dans la guilde quand le canal de l'addon est refusé ou muet : coupés (/ov guild on pour les rétablir). Ceux de vos camarades restent lus."
},
es = {
    GUIDE_BTN_TOOLTIP = "Guía de Forever (3 páginas)",
    GUIDE_PAGE1_TITLE = "Primeros pasos", GUIDE_PAGE2_TITLE = "Capturas y recursos",
    GUIDE_PAGE3_TITLE = "Fortalezas, avanzadas y clasificación",
    GUIDE_SECTION_TRAVEL = "Mundo abierto",
    GUIDE_TRAVEL_ALLIANCE = "- Ve a un frente de Overlord en el mundo abierto.\n- El mapa muestra los puntos que puedes capturar; el Próximo objetivo del panel te indica el camino.\n- En el mapa del mundo, un gran emblema sobre cada continente muestra la facción que domina más frentes en él.",
    GUIDE_SECTION_RULES = "Antes de capturar",
    GUIDE_RULES_BODY = "- Activa el JcJ (/pvp) y quédate a pie dentro del círculo.\n- La captura se detiene si vas montado, volando, en forma de viaje, en un vehículo o un taxi, en sigilo o muerto.\n- Si entras volando en un círculo, te desmontas tras un breve aviso.",
    GUIDE_SECTION_PROGRESS = "Los siete frentes",
    GUIDE_PROGRESS_BODY = "- Tierras Altas de Arathi, Loch Modan, Durotar, Vallefresno, Bosque de Elwynn, Montañas Crestagrana y Laderas de Trabalomas: una ruta de captura entre dos capitales.\n- Un punto se abre cuando los anteriores son tuyos; puede haber varias ramas abiertas a la vez. Los puntos abiertos se ven en amarillo con espadas cruzadas.\n- Las muertes honorables (MH) en el mundo abierto cuentan una vez a cualquier nivel, según el contador oficial de Blizzard.",
    GUIDE_SECTION_SHARD = "Layers y sincronización",
    GUIDE_SHARD_BODY = "- Capturas y clasificación se comparten con todos los jugadores de tu tipo de reino (JcJ, Normal, Rol, Rol JcJ o Hardcore): canal del addon, hermandad, grupo y amigos de Battle.net.\n- Si el juego rechaza el canal del addon o nadie responde en él, los datos pasan por tu hermandad (/ov guild off para detenerlo). Overlord también intercambia datos, por susurros invisibles, con algunos jugadores de la lista de miembros del canal, sea cual sea su hermandad: capturas, asedios, combates (Actividad reciente) y matanzas de hermandad pasan de mano en mano en pocos segundos, mapas y clasificación siguen pasando de una hermandad a otra, incluso sin hermandad. Los jugadores encontrados así se vuelven a encontrar después, incluso cuando el juego oculta la lista de miembros.\n- La clasificación se completa sola en segundo plano, incluso con la ventana cerrada.\n- El punto en la cabecera del panel muestra el estado de la red, verde mientras el canal, su lista de miembros o tu hermandad transporte tus datos (canal rechazado incluido); /ov network da los detalles.\n- Un layer es tu copia del mundo abierto: forma grupo para luchar junto a aliados de otro layer.\n- Layers: haz clic en el botón Layers del panel, o en el número de layer arriba a la izquierda, para listar los jugadores que Overlord oye y su layer. Unirse pide una invitación a un voluntario de ese layer; sales del grupo solo tras el cambio. Solo voluntarios: «Ayudar a otros» está desactivado por defecto. Los voluntarios llevan un icono de portal en la lista y se les pregunta primero; un rechazo dice por qué.",
    GUIDE_SECTION_PANEL = "Panel de Overlord",
    GUIDE_PANEL_BODY = "- Botón del minimapa o /ov show (/ov solo lista los comandos).\n- Elige un frente: sus puntos, la captura en curso, los combates recientes y la barra de dominación semanal (pasa el ratón: victorias de frente de la semana).\n- Botones: Grupos JcJ, Cuerno, Comandar, la clasificación y el Salón de la Fama.\n- Tu platino, Atacar y Reforzar están en la tarjeta Próximo objetivo.\n- Reabre esta guía desde el panel o con /ov guide.",
    GUIDE_SECTION_OPTIONS = "Opciones y comandos",
    GUIDE_OPTIONS_BODY = "- En el panel, o Esc → Opciones → AddOns → Overlord.\n- Marcador del objetivo, mapa del mundo, Iconos del minimapa, sonidos, escala del panel, panel flotante, Némesis y alertas de hermandad.\n- Comandos útiles: /ov lb (clasificación), /ov map (mapa del mundo: completo, compacto, solo círculos u oculto, también con el botón de Overlord en la esquina del mapa: clic derecho + arrastrar lo mueve, /ov map button lo oculta), /ov sync (ponerse al día), /ov guildkills.",
    GUIDE_SECTION_CONTEST = "Captura y disputa",
    GUIDE_CONTEST_BODY = "- Círculo normal: quédate 2 minutos; si sales, el progreso retrocede.\n- Tantos enemigos como tú, o más, lo hacen retroceder, más rápido cuanto más te superan.\n- Capital enemiga: 8 minutos. Recuperar la tuya: 2 minutos.\n- Un punto existe en cada layer: un atacante en otro layer no puede ser visto ni detenido desde el tuyo. El chat te avisa; únete a su layer para luchar.\n- Una captura espera, en pausa, mientras un punto que necesita es atacado después de su inicio.\n- Un solo temporizador por punto: si sois varios en él, cuenta la captura que empezó primero y las demás la siguen. Si su capturador deja el punto o muere, un miembro del grupo presente en el punto continúa la captura.",
    GUIDE_SECTION_SIEGE = "Victoria en la capital",
    GUIDE_SIEGE_BODY = "- Cuando todos los demás puntos del frente sean tuyos, asalta la capital enemiga.\n- Tomarla gana el frente: +1 % de dominación semanal y una tregua de 15 minutos.\n- Tras la tregua, la conquista se mantiene, capital caída incluida, hasta que su facción la recupere (una facción siempre puede atacar su propia capital).\n- Una nueva victoria en el mismo frente solo cuenta 6 horas después de la anterior.",
    GUIDE_SIEGE_BODY_NOTRUCE = "- Cuando todos los demás puntos del frente sean tuyos, asalta la capital enemiga.\n- Tomarla gana el frente: +1 % de dominación semanal.\n- La conquista se mantiene, capital caída incluida, hasta que su facción la recupere (una facción siempre puede atacar su propia capital).\n- Una nueva victoria en el mismo frente solo cuenta 6 horas después de la anterior.",
    GUIDE_SECTION_GOLD = "Minas de platino",
    GUIDE_GOLD_BODY = "Minas en el mapa:\n%s\n\n- En el círculo de una mina, con el JcJ activo (/pvp): 1 de platino cada 3 segundos (máximo personal 100); extraer una veta da 5.\n- Atacar, 25 de platino: tu próxima captura dura 60 segundos menos (no capitales).\n- Reforzar, 25 de platino: la próxima captura enemiga de uno de tus puntos dura 60 segundos más (no capitales).\n- Las reservas compartidas se regeneran.",
    GUIDE_SECTION_FEATURED = "Frente del día y reinicio semanal",
    GUIDE_FEATURED_BODY = "- El frente del día cambia cada día a medianoche, hora de tu equipo.\n- Cada MH oficial en él da +1 de platino.\n- La clasificación, la dominación y el mapa de guerra se reinician cada semana, según el horario de tu región (América: martes, Europa: miércoles, Corea y Taiwán: jueves por la mañana).",
    GUIDE_SECTION_GUILD_KEEP = "Fortalezas de hermandad",
    GUIDE_GUILD_KEEP_BODY = "Cinco fortalezas: Sierra Espolón, Los Humedales, Tierras Inhóspitas, Los Baldíos y Mulgore.\n%s\n\n- Abiertas a cualquier hora: un miembro de hermandad mantiene el cuadro %d minutos.\n- Al salir baja el progreso; los enemigos en igual número lo detienen y en mayoría lo hacen retroceder.\n- Solo la facción rival puede disputarla o tomarla.\n- Sigue con su hermandad hasta una captura rival o el reinicio semanal; la tabla de fortalezas de la clasificación cuenta las capturas y su descripción indica quién la tomó.\n- El icono de pergamino en la cabecera de avanzadas de la clasificación muestra los conquistadores y las rivalidades entre hermandades de la semana.",
    GUIDE_SECTION_OUTPOST = "Avanzadas de hermandad",
    GUIDE_OUTPOST_BODY = "- Una por frente, más la Capilla de Savix (Bosque de Argénteos), el Pabellón de Aeythyr (Tierras de la Peste del Este), la Cueva del oso de Lesi (Costa Oscura) y el Pozo de la Luna de Anad'Ora (Feralas).\n- Reglas de las fortalezas, pero 5 minutos.\n- Mientras una hermandad de tu facción tenga la avanzada de un frente, el enemigo necesita 30 segundos más en los puntos normales de ese frente.",
    GUIDE_SECTION_FACTION_CALL = "Cuerno y General",
    GUIDE_FACTION_CALL_BODY = "- Cuerno: en un frente activo, el botón abre un cuerno; un clic en el cuerno envía un aviso de banda a todos los aliados de tu facción con Overlord (una vez cada 4 horas para toda la facción).\n- Comandar: un líder de grupo o banda se convierte en el General de su facción, visible en el mapa, el minimapa y su placa de nombre; todos reciben un aviso cuando cae.",
    GUIDE_SECTION_ALERTS = "Alertas",
    GUIDE_ALERTS_BODY = "- Némesis: los cinco mejores asesinos enemigos de la semana llevan una calavera en su placa de nombre, y el chat te avisa cuando aparece uno (se activa o desactiva en las opciones). Tu golpe final a uno de ellos da +10 de platino (una vez por jugador cada media hora).\n- Matanza enemiga: una hermandad enemiga acumula MH en poco tiempo (/ov guildkills on u off).\n- Matanza aliada, en verde: una hermandad de tu facción hace lo mismo (/ov guildkills allies on u off).\n- Las alertas de captura, de avanzadas y de minas vienen de la zona en la que estás: «Alertas de captura» en las opciones las amplía a tu continente o a todo el mundo. Las fortalezas y avanzadas de tu hermandad, las matanzas, los avisos del Cuerno y las victorias totales te llegan siempre. Las fortalezas y avanzadas de otras hermandades no se anuncian, salvo que marques «Alertas de fortalezas y avanzadas de otras hermandades».\n- Grandes batallas: una línea de chat cuando un combate alcanza 50 muertes o más en 5 minutos, en cualquier parte del mundo («Alertas de gran batalla» en las opciones).",
    GUIDE_SECTION_GROUPS = "Grupos JcJ",
    GUIDE_GROUPS_BODY = "- Grupos JcJ (botón del panel o /ov groups): publica tu grupo con un objetivo, un lugar, un tamaño y un nivel mínimo, o apúntate a uno de la lista.\n- Los anuncios llegan a los jugadores de Overlord de tu facción. El líder te invita, automáticamente o tras aprobar tu solicitud; la invitación del juego la aceptas tú.\n- Puedes unirte a un grupo cada 2 minutos. Desactivado en instancias.",
    GUIDE_SECTION_TOOLS = "Clasificación y Salón de la Fama",
    GUIDE_TOOLS_BODY = "- Clasificación semanal (/ov lb): MH, hermandades con sus miembros clasificados (un clic en una hermandad los muestra todos), puntos de hermandad (MH y capturas; un clic en MH o Puntos ordena las hermandades), fortalezas y avanzadas, buscador, tiempo restante y tu puesto; en la cabecera, entre los totales y tu puesto, una flecha verde mientras llegan datos de la clasificación y luego una marca verde cuando está al día.\n- /ov sync pide datos a los jugadores accesibles.\n- Salón de la Fama (botón del panel): campeones de la semana pasada, tus hazañas y los donantes.",
    GUIDE_SECTION_RANKS = "Rango Overlord",
    GUIDE_RANKS_BODY = "- Una nueva pestaña en tu hoja de personaje (logotipo de Overlord): quince rangos; un rango ganado no baja.\n- Los rangos 1 a 10 se pagan con Gloria: cada muerte honorable en el mundo abierto cuenta, y una captura cuenta más. Solo cuenta lo que Overlord ve a partir de ahora.\n- Los rangos 11 a 14 piden además tres semanas terminadas en el top 100, 25, 10 y luego 3 de la clasificación semanal de tu facción; el último, Overlord, pide más Gloria y cinco semanas terminadas como primero de tu facción (con al menos 1.000 muertes honorables cada una). Las semanas se suman y no tienen que ser seguidas; una semana mejor cuenta también para los tops más amplios. Una semana cuenta a partir de 100 muertes honorables, si jugaste durante sus últimas 24 horas. Una semana en el top 3 o terminada como primero pide además que tu clasificación se haya comparado con la de otros jugadores durante esas 24 horas.\n- Tu rango se guarda únicamente en este ordenador, para este personaje, sin ninguna copia en otro lugar: si los datos de addons del juego se borran o se pierden (juego reinstalado, disco cambiado, otro ordenador), el rango vuelve a cero y no se puede recuperar.\n- A partir del rango 11, los demás jugadores ven su insignia junto a tu nombre, en la clasificación y en las placas de nombre, una vez que su propio cliente lo ha comprobado: los de tu facción con los datos del juego y sus propias clasificaciones semanales (cuando se han cruzado contigo en semanas distintas), los de la otra facción con sus propias clasificaciones semanales. Un jugador que se perdió tus mejores semanas puede verla más tarde, o nunca.\n- Cada rango alcanzado se anuncia en pantalla y figura en el Salón de la Fama, en Tus hazañas.",
    -- 2.1.1: /ov guild.
    HELP_GUILD_LANE = "|cFFFFFF00/ov guild [on || off]|r: mensajes de red en tu hermandad cuando el juego rechaza el canal del addon o nadie responde en él",
    GUILD_LANE_ON = "Mensajes de red en la hermandad cuando se rechaza el canal del addon o nadie responde: activados (/ov guild off para cortarlos).",
    REPORT_WINDOW_TITLE = "Overlord: informe de red",
    REPORT_SELECT_ALL = "Seleccionar todo (luego Ctrl+C)",
    GUILD_LANE_OFF = "Mensajes de red en la hermandad cuando se rechaza el canal del addon o nadie responde: cortados (/ov guild on para restablecerlos). Los de tus compañeros se siguen leyendo."
},
de = {
    GUIDE_BTN_TOOLTIP = "Forever-Anleitung (3 Seiten)",
    GUIDE_PAGE1_TITLE = "Erste Schritte", GUIDE_PAGE2_TITLE = "Eroberung und Ressourcen",
    GUIDE_PAGE3_TITLE = "Festungen, Außenposten und Rangliste",
    GUIDE_SECTION_TRAVEL = "In die offene Welt",
    GUIDE_TRAVEL_ALLIANCE = "- Reist zu einer Overlord-Front in der offenen Welt.\n- Die Karte zeigt die Punkte, die ihr erobern könnt; das nächste Ziel im Panel zeigt den Weg.\n- Auf der Weltkarte zeigt ein großes Wappen über jedem Kontinent die Fraktion, die dort die meisten Fronten beherrscht.",
    GUIDE_SECTION_RULES = "Vor der Eroberung",
    GUIDE_RULES_BODY = "- Aktiviert PvP (/pvp) und bleibt zu Fuß im Kreis.\n- Die Eroberung pausiert beritten, im Flug, in Reisegestalt, in einem Fahrzeug oder auf einer Flugroute, verstohlen oder tot.\n- Wer in einen Kreis fliegt, wird nach einer kurzen Warnung abgesetzt.",
    GUIDE_SECTION_PROGRESS = "Die sieben Fronten",
    GUIDE_PROGRESS_BODY = "- Arathihochland, Loch Modan, Durotar, Eschental, Wald von Elwynn, Rotkammgebirge und Vorgebirge des Hügellands: ein Eroberungsweg zwischen zwei Hauptstädten.\n- Ein Punkt öffnet sich, sobald die Punkte davor euch gehören; mehrere Zweige können gleichzeitig offen sein. Offene Punkte erscheinen gelb mit gekreuzten Schwertern.\n- Ehrenhafte Siege (ES) in der offenen Welt zählen auf jeder Stufe einmal, nach Blizzards offiziellem Zähler.",
    GUIDE_SECTION_SHARD = "Layer und Synchronisierung",
    GUIDE_SHARD_BODY = "- Eroberungen und Ranglisten werden mit allen Spielern eures Realmtyps geteilt (PvP, Normal, RP, RP-PvP oder Hardcore): Addon-Kanal, Gilde, Gruppe und Battle.net-Freunde.\n- Lehnt das Spiel den Addon-Kanal ab oder antwortet dort niemand, laufen die Daten über eure Gilde (/ov guild off schaltet das ab). Overlord tauscht außerdem über unsichtbares Flüstern Daten mit einigen Spielern aus der Mitgliederliste des Kanals aus, egal welcher Gilde: Eroberungen, Belagerungen, Kämpfe (Kürzliche Aktivität) und Gildengemetzel gehen in Sekunden von Hand zu Hand, Karten und Ranglisten wandern weiter von Gilde zu Gilde, auch ohne Gilde. So gefundene Spieler werden später wiedergefunden, auch wenn das Spiel die Mitgliederliste verbirgt.\n- Die Rangliste füllt sich von selbst im Hintergrund, auch bei geschlossenem Fenster.\n- Der Punkt im Kopf des Panels zeigt den Zustand des Netzwerks, grün, solange der Kanal, seine Mitgliederliste oder eure Gilde eure Daten trägt (auch bei abgelehntem Kanal); /ov network zeigt Details.\n- Ein Layer ist eure Kopie der offenen Welt: Bildet eine Gruppe, um mit Verbündeten auf einem anderen Layer zu kämpfen.\n- Layer: Klicke im Fenster auf den Button Layer oder oben links auf die Layernummer, um die Spieler, die Overlord hört, mit ihrem Layer aufzulisten. Beitreten bittet einen Freiwilligen auf diesem Layer um eine Einladung; nach dem Wechsel verlässt du die Gruppe von selbst. Nur Freiwillige: „Anderen helfen“ ist standardmäßig aus. Freiwillige tragen in der Liste ein Portalsymbol und werden zuerst gefragt; eine Absage nennt den Grund.",
    GUIDE_SECTION_PANEL = "Overlord-Panel",
    GUIDE_PANEL_BODY = "- Minikarten-Schaltfläche oder /ov show (/ov allein listet die Befehle).\n- Wählt eine Front: ihre Punkte, die laufende Eroberung, jüngste Kämpfe und die wöchentliche Dominanzleiste (Maus darüber: Frontsiege der Woche).\n- Schaltflächen: PvP-Gruppen, Kriegshorn, Kommando, die Rangliste und die Ruhmeshalle.\n- Euer Platin, Angriff und Verstärken stehen in der Karte des nächsten Ziels.\n- Öffnet diese Anleitung im Panel oder mit /ov guide erneut.",
    GUIDE_SECTION_OPTIONS = "Einstellungen und Befehle",
    GUIDE_OPTIONS_BODY = "- Im Panel oder Esc → Optionen → AddOns → Overlord.\n- Zielmarkierung, Weltkarte, Minimap-Symbole, Töne, Panelgröße, schwebende Leiste, Nemesis und Gildenwarnungen.\n- Nützliche Befehle: /ov lb (Rangliste), /ov map (Weltkarte: vollständig, kompakt, nur Kreise oder ausgeblendet, auch über den Overlord-Knopf in der Kartenecke: Rechtsklick + Ziehen verschiebt ihn, /ov map button blendet ihn aus), /ov sync (aufholen), /ov guildkills.",
    GUIDE_SECTION_CONTEST = "Eroberung und Gegenwehr",
    GUIDE_CONTEST_BODY = "- Normaler Kreis: 2 Minuten bleiben; wer ihn verlässt, verliert Fortschritt.\n- Gleich viele oder mehr Gegner drängen ihn zurück, umso schneller, je größer ihre Überzahl.\n- Feindliche Hauptstadt: 8 Minuten. Die eigene zurückerobern: 2 Minuten.\n- Ein Punkt existiert auf jedem Layer: Ein Angreifer auf einem anderen Layer ist von deinem aus weder zu sehen noch aufzuhalten. Der Chat sagt es dir; wechsle auf seinen Layer, um zu kämpfen.\n- Eine Eroberung wartet pausiert, solange ein dafür nötiger Punkt nach ihrem Beginn angegriffen wird.\n- Ein Timer pro Punkt: Stehen mehrere von euch darauf, zählt die zuerst begonnene Eroberung, die anderen folgen ihr. Verlässt der Eroberer den Punkt oder stirbt er, führt ein Gruppenmitglied auf dem Punkt die Eroberung fort.",
    GUIDE_SECTION_SIEGE = "Sieg an der Hauptstadt",
    GUIDE_SIEGE_BODY = "- Sobald alle anderen Punkte der Front euch gehören, greift die feindliche Hauptstadt an.\n- Ihre Eroberung gewinnt die Front: +1 % Wochendominanz und 15 Minuten Waffenruhe.\n- Nach der Waffenruhe bleibt die Eroberung bestehen, die gefallene Hauptstadt eingeschlossen, bis ihre Fraktion sie zurückerobert (eine Fraktion kann ihre eigene Hauptstadt immer angreifen).\n- Ein neuer Sieg an derselben Front zählt erst 6 Stunden nach dem vorigen.",
    GUIDE_SIEGE_BODY_NOTRUCE = "- Sobald alle anderen Punkte der Front euch gehören, greift die feindliche Hauptstadt an.\n- Ihre Eroberung gewinnt die Front: +1 % Wochendominanz.\n- Die Eroberung bleibt bestehen, die gefallene Hauptstadt eingeschlossen, bis ihre Fraktion sie zurückerobert (eine Fraktion kann ihre eigene Hauptstadt immer angreifen).\n- Ein neuer Sieg an derselben Front zählt erst 6 Stunden nach dem vorigen.",
    GUIDE_SECTION_GOLD = "Platinminen",
    GUIDE_GOLD_BODY = "Minen auf der Karte:\n%s\n\n- Im Kreis einer Mine, mit aktivem PvP (/pvp): alle 3 Sekunden 1 Platin (persönliches Maximum 100); ein Erzvorkommen gibt 5.\n- Angriff, 25 Platin: eure nächste Eroberung dauert 60 Sekunden weniger (keine Hauptstädte).\n- Verstärken, 25 Platin: die nächste feindliche Eroberung eines eurer Punkte dauert 60 Sekunden länger (keine Hauptstädte).\n- Der gemeinsame Vorrat füllt sich wieder auf.",
    GUIDE_SECTION_FEATURED = "Front des Tages und Wochenreset",
    GUIDE_FEATURED_BODY = "- Die Front des Tages wechselt jeden Tag um Mitternacht nach eurer Ortszeit.\n- Jeder offizielle ES dort bringt +1 Overlord-Platin.\n- Rangliste, Dominanz und Kriegskarte werden jede Woche nach dem Zeitplan eurer Region zurückgesetzt (Amerika: Dienstag, Europa: Mittwoch, Korea und Taiwan: Donnerstagmorgen).",
    GUIDE_SECTION_GUILD_KEEP = "Gildenfestungen",
    GUIDE_GUILD_KEEP_BODY = "Fünf Festungen: Steinkrallengebirge, Sumpfland, Ödland, Brachland und Mulgore.\n%s\n\n- Jederzeit offen: Ein Gildenmitglied hält das Quadrat %d Minuten.\n- Wer es verlässt, verliert Fortschritt; gleich viele Gegner stoppen ihn, mehr Gegner drängen ihn zurück.\n- Nur die Gegenfraktion kann sie angreifen oder einnehmen.\n- Sie bleibt bei ihrer Gilde bis zur feindlichen Eroberung oder zum Wochenreset; die Festungstabelle der Rangliste zählt die Eroberungen und ihr Tooltip nennt den Eroberer.\n- Das Schriftrollen-Symbol im Außenposten-Kopf der Rangliste zeigt die Eroberer und Gildenrivalitäten der Woche.",
    GUIDE_SECTION_OUTPOST = "Gilden-Außenposten",
    GUIDE_OUTPOST_BODY = "- Einer pro Front, dazu die Kapelle von Savix (Silberwald), Aeythyrs Jagdhütte (Östliche Pestländer), Lesis Bärenhöhle (Dunkelküste) und den Mondbrunnen von Anad'Ora (Feralas).\n- Festungsregeln, aber 5 Minuten.\n- Solange eine Gilde eurer Fraktion den Außenposten einer Front hält, braucht der Feind an den normalen Punkten dieser Front 30 Sekunden länger.",
    GUIDE_SECTION_FACTION_CALL = "Kriegshorn und General",
    GUIDE_FACTION_CALL_BODY = "- Kriegshorn: an einer aktiven Front öffnet die Schaltfläche ein Horn; ein Klick auf das Horn sendet eine Schlachtzugswarnung an alle Overlord-Verbündeten eurer Fraktion (einmal alle 4 Stunden für die ganze Fraktion).\n- Kommando: Ein Gruppen- oder Schlachtzugsleiter wird General seiner Fraktion, sichtbar auf Karte, Minikarte und Namensplakette; alle erfahren es, wenn er fällt.",
    GUIDE_SECTION_ALERTS = "Warnungen",
    GUIDE_ALERTS_BODY = "- Nemesis: Die fünf besten feindlichen Kämpfer der Woche tragen einen Totenkopf auf ihrer Namensplakette, und der Chat warnt euch, wenn einer auftaucht (in den Optionen an- oder abschaltbar). Euer Todesstoß gegen einen von ihnen bringt +10 Platin (einmal pro Spieler und halbe Stunde).\n- Feindliches Gemetzel: Eine feindliche Gilde sammelt in kurzer Zeit viele ES (/ov guildkills on oder off).\n- Verbündetes Gemetzel, in Grün: Eine Gilde eurer Fraktion tut es (/ov guildkills allies on oder off).\n- Eroberungs-, Außenposten- und Minenwarnungen kommen aus der Zone, in der ihr seid: „Eroberungswarnungen“ in den Optionen erweitert sie auf euren Kontinent oder die ganze Welt. Die Festungen und Außenposten eurer Gilde, Gemetzel, das Kriegshorn und totale Siege erreichen euch immer. Festungen und Außenposten anderer Gilden bleiben stumm, außer ihr aktiviert „Festungs- und Außenpostenwarnungen anderer Gilden“.\n- Große Schlachten: eine Chatzeile, wenn ein Kampf 50 oder mehr Kills in 5 Minuten erreicht, überall auf der Welt („Warnungen bei großen Schlachten“ in den Optionen).",
    GUIDE_SECTION_GROUPS = "PvP-Gruppen",
    GUIDE_GROUPS_BODY = "- PvP-Gruppen (Schaltfläche im Panel oder /ov groups): Veröffentlicht Eure Gruppe mit Ziel, Ort, Größe und Mindeststufe oder meldet Euch bei einer gelisteten an.\n- Einträge erreichen die Overlord-Spieler Eurer Fraktion. Der Anführer lädt Euch ein, automatisch oder nach Bestätigung Eurer Anfrage; die Einladung des Spiels nehmt Ihr selbst an.\n- Ihr könnt alle 2 Minuten einer Gruppe beitreten. In Instanzen aus.",
    GUIDE_SECTION_TOOLS = "Rangliste und Ruhmeshalle",
    GUIDE_TOOLS_BODY = "- Wochenrangliste (/ov lb): ES, Gilden mit ihren gelisteten Mitgliedern (ein Klick auf eine Gilde zeigt sie alle), Gildenwertung (ES und Eroberungen; ein Klick auf ES oder Wertung sortiert die Gilden), Festungen und Außenposten, Suchfeld, Restzeit und euer Rang; in der Kopfzeile zwischen den Summen und eurem Rang ein grüner Pfeil, solange Ranglistendaten eintreffen, dann ein grüner Haken, sobald sie aktuell ist.\n- /ov sync fordert Daten von erreichbaren Spielern an.\n- Ruhmeshalle (Schaltfläche im Panel): Champions der letzten Woche, eure Heldentaten und die Spender.",
    GUIDE_SECTION_RANKS = "Overlord-Rang",
    GUIDE_RANKS_BODY = "- Ein neuer Reiter auf Eurem Charakterbogen (Overlord-Logo): fünfzehn Ränge; ein erreichter Rang sinkt nie.\n- Die Ränge 1 bis 10 werden mit Ruhm bezahlt: Jeder ehrenhafte Sieg in der offenen Welt zählt, eine Eroberung zählt mehr. Es zählt nur, was Overlord ab jetzt sieht.\n- Die Ränge 11 bis 14 verlangen zusätzlich drei Wochen, die Ihr in den Top 100, 25, 10 und dann 3 der Wochenrangliste Eurer Fraktion beendet; der letzte, Overlord, verlangt mehr Ruhm und fünf Wochen, die Ihr als Erster Eurer Fraktion beendet (mit mindestens 1.000 ehrenhaften Siegen pro Woche). Die Wochen summieren sich und müssen nicht aufeinander folgen; eine bessere Woche zählt auch für die größeren Tops. Eine Woche zählt ab 100 ehrenhaften Siegen, wenn Ihr in ihren letzten 24 Stunden gespielt habt. Eine Woche in den Top 3 oder als Erster verlangt zusätzlich, dass Eure Rangliste in diesen 24 Stunden mit der anderer Spieler verglichen wurde.\n- Euer Rang wird nur auf diesem Computer gespeichert, für diesen Charakter, ohne Kopie an einem anderen Ort: Werden die Addon-Daten des Spiels gelöscht oder gehen sie verloren (Spiel neu installiert, Festplatte gewechselt, anderer Computer), beginnt der Rang wieder bei null und kann nicht wiederhergestellt werden.\n- Ab Rang 11 sehen andere Spieler sein Abzeichen neben Eurem Namen, in der Rangliste und auf den Namensplaketten, sobald ihr eigener Client ihn geprüft hat: Spieler Eurer Fraktion mit den Daten des Spiels und ihren eigenen Wochenranglisten (sobald sie Euch in verschiedenen Wochen begegnet sind), Spieler der anderen Fraktion mit ihren eigenen Wochenranglisten. Ein Spieler, der Eure besten Wochen verpasst hat, sieht es vielleicht später oder nie.\n- Jeder erreichte Rang wird auf dem Bildschirm angekündigt und steht in der Ruhmeshalle unter „Eure Heldentaten“.",
    -- 2.1.1: /ov guild.
    HELP_GUILD_LANE = "|cFFFFFF00/ov guild [on || off]|r: Netzwerknachrichten in eurer Gilde, wenn das Spiel den Addon-Kanal ablehnt oder dort niemand antwortet",
    GUILD_LANE_ON = "Netzwerknachrichten in der Gilde, wenn der Addon-Kanal abgelehnt wird oder stumm bleibt: an (/ov guild off zum Abschalten).",
    REPORT_WINDOW_TITLE = "Overlord: Netzwerkbericht",
    REPORT_SELECT_ALL = "Alles markieren (dann Strg+C)",
    GUILD_LANE_OFF = "Netzwerknachrichten in der Gilde, wenn der Addon-Kanal abgelehnt wird oder stumm bleibt: aus (/ov guild on zum Einschalten). Die eurer Gildenmitglieder werden weiter gelesen."
},
ru = {
    GUIDE_BTN_TOOLTIP = "Руководство Forever (3 страницы)",
    GUIDE_PAGE1_TITLE = "Первые шаги", GUIDE_PAGE2_TITLE = "Захват и ресурсы",
    GUIDE_PAGE3_TITLE = "Крепости, аванпосты и рейтинг",
    GUIDE_SECTION_TRAVEL = "Открытый мир",
    GUIDE_TRAVEL_ALLIANCE = "- Отправляйтесь на фронт Overlord в открытом мире.\n- Карта показывает точки для захвата; следующая цель на панели подскажет путь.\n- На карте мира большой герб над каждым континентом показывает фракцию, которая господствует там на большинстве фронтов.",
    GUIDE_SECTION_RULES = "Перед захватом",
    GUIDE_RULES_BODY = "- Включите PvP (/pvp) и стойте в круге пешком.\n- Захват замирает, если вы верхом, в полёте, в походном облике, в транспорте или на такси, в незаметности или мертвы.\n- Если влететь в круг, после короткого предупреждения вы будете спешены.",
    GUIDE_SECTION_PROGRESS = "Семь фронтов",
    GUIDE_PROGRESS_BODY = "- Нагорье Арати, Лок Модан, Дуротар, Ясеневый лес, Элвиннский лес, Красногорье и Предгорья Хилсбрада: цепочка захвата между двумя столицами.\n- Точка открывается, когда предыдущие ваши; несколько ветвей могут быть открыты одновременно. Открытые точки отмечены жёлтым цветом и скрещёнными мечами.\n- Почётные победы (ПП) в открытом мире засчитываются на любом уровне один раз, по официальному счётчику Blizzard.",
    GUIDE_SECTION_SHARD = "Слои и синхронизация",
    GUIDE_SHARD_BODY = "- Захваты и рейтинг передаются всем игрокам вашего типа миров (PvP, обычный, RP, RP-PvP или Hardcore): канал аддона, гильдия, группа и друзья Battle.net.\n- Если игра отклоняет канал аддона или в нём никто не отвечает, данные идут через вашу гильдию (/ov guild off, чтобы отключить). Overlord также обменивается данными невидимым шёпотом с несколькими игроками из списка участников канала, из любой гильдии: захваты, осады, бои (Недавняя активность) и разгромы гильдий передаются из рук в руки за секунды, карты и рейтинг по-прежнему переходят между гильдиями, даже без гильдии. Найденные так игроки находятся снова и позже, даже когда игра скрывает список участников.\n- Рейтинг заполняется сам в фоне, даже при закрытом окне.\n- Точка в заголовке панели показывает состояние сети и остаётся зелёной, пока ваши данные передаёт канал, его список участников или ваша гильдия (даже при отклонённом канале); подробности — /ov network.\n- Слой (layer) — ваша копия открытого мира: вступите в группу, чтобы сражаться с союзниками с другого слоя.\n- Слои: нажмите кнопку «Слои» на панели или номер слоя в её левом верхнем углу, чтобы увидеть игроков, которых слышит Overlord, и их слои. «Перейти» просит приглашение у добровольца с этого слоя; после перехода вы сами покидаете группу. Только добровольцы: «Помогать другим» по умолчанию выключено. Добровольцы отмечены в списке значком портала, их спрашивают первыми; при отказе указана причина.",
    GUIDE_SECTION_PANEL = "Панель Overlord",
    GUIDE_PANEL_BODY = "- Кнопка у мини-карты или /ov show (/ov без параметров — список команд).\n- Выберите фронт: его точки, текущий захват, недавние бои и полоса недельного господства (наведите курсор: победы на фронтах за неделю).\n- Кнопки: PvP-группы, К оружию, Управление, рейтинг и Зал славы.\n- Ваша платина, Атака и Укрепить — в карточке следующей цели.\n- Руководство снова открывается из панели или командой /ov guide.",
    GUIDE_SECTION_OPTIONS = "Настройки и команды",
    GUIDE_OPTIONS_BODY = "- В панели или Esc → Настройки → AddOns → Overlord.\n- Метка цели, карта мира, Значки на мини-карте, звуки, масштаб панели, плавающая панель, Немезида и оповещения о гильдиях.\n- Полезные команды: /ov lb (рейтинг), /ov map (карта мира: полный, компактный, только круги или скрытый режим, также кнопкой Overlord в углу карты: перетаскивание правой кнопкой перемещает её, /ov map button скрывает), /ov sync (синхронизация), /ov guildkills.",
    GUIDE_SECTION_CONTEST = "Захват и оспаривание",
    GUIDE_CONTEST_BODY = "- Обычный круг: 2 минуты; если выйти, прогресс откатывается.\n- Столько же врагов или больше откатывают его, тем быстрее, чем больше их перевес.\n- Вражеская столица: 8 минут. Возврат своей: 2 минуты.\n- Точка существует на каждом слое: атакующего на другом слое нельзя ни увидеть, ни остановить с вашего. Чат сообщит об этом; перейдите на его слой, чтобы сражаться.\n- Захват ждёт на паузе, пока нужная ему точка атакована после его начала.\n- Один таймер на точку: если вас на ней несколько, считается захват, начатый первым, остальные следуют за ним. Если захватчик покидает точку или погибает, захват продолжает участник группы, стоящий на точке.",
    GUIDE_SECTION_SIEGE = "Победа у столицы",
    GUIDE_SIEGE_BODY = "- Когда все остальные точки фронта ваши, штурмуйте вражескую столицу.\n- Её захват приносит победу на фронте: +1 % недельного господства и 15 минут перемирия.\n- После перемирия завоевания остаются, включая павшую столицу, пока её фракция её не отобьёт (фракция всегда может атаковать свою столицу).\n- Новая победа на том же фронте засчитывается только через 6 часов после предыдущей.",
    GUIDE_SIEGE_BODY_NOTRUCE = "- Когда все остальные точки фронта ваши, штурмуйте вражескую столицу.\n- Её захват приносит победу на фронте: +1 % недельного господства.\n- Завоевания остаются, включая павшую столицу, пока её фракция её не отобьёт (фракция всегда может атаковать свою столицу).\n- Новая победа на том же фронте засчитывается только через 6 часов после предыдущей.",
    GUIDE_SECTION_GOLD = "Платиновые рудники",
    GUIDE_GOLD_BODY = "Рудники на карте:\n%s\n\n- В круге рудника, с включённым PvP (/pvp): 1 ед. платины каждые 3 секунды (личный предел 100); добытая жила даёт 5.\n- Атака, 25 платины: ваш следующий захват короче на 60 секунд (кроме столиц).\n- Укрепить, 25 платины: следующий вражеский захват вашей точки дольше на 60 секунд (кроме столиц).\n- Общий запас рудника постепенно восстанавливается.",
    GUIDE_SECTION_FEATURED = "Фронт дня и недельный сброс",
    GUIDE_FEATURED_BODY = "- Фронт дня меняется каждый день в полночь по времени вашего компьютера.\n- Каждая официальная ПП на нём даёт +1 ед. платины.\n- Рейтинг, господство и карта войны сбрасываются каждую неделю по расписанию вашего региона (Америка: вторник, Европа: среда, Корея и Тайвань: утро четверга).",
    GUIDE_SECTION_GUILD_KEEP = "Гильдейские крепости",
    GUIDE_GUILD_KEEP_BODY = "Пять крепостей: Когтистые горы, Болотина, Бесплодные земли, Степи и Мулгор.\n%s\n\n- Открыты в любое время: член гильдии удерживает квадрат %d минут.\n- При выходе прогресс откатывается; равное число врагов останавливает его, превосходство откатывает.\n- Оспорить или захватить крепость может только другая фракция.\n- Она остаётся у гильдии до вражеского захвата или недельного сброса; таблица крепостей в рейтинге считает захваты, а подсказка называет захватчика.\n- Значок свитка в заголовке аванпостов рейтинга показывает захватчиков и соперничество гильдий за неделю.",
    GUIDE_SECTION_OUTPOST = "Гильдейские аванпосты",
    GUIDE_OUTPOST_BODY = "- По одному на каждый фронт, плюс Часовня Savix (Серебряный бор), Охотничий домик Aeythyr (Восточные Чумные земли), Медвежья пещера Lesi (Темные берега) и Лунный колодец Anad'Ora (Фералас).\n- Правила крепостей, но 5 минут.\n- Пока гильдия вашей фракции держит аванпост фронта, враг захватывает обычные точки этого фронта на 30 секунд дольше.",
    GUIDE_SECTION_FACTION_CALL = "К оружию и Генерал",
    GUIDE_FACTION_CALL_BODY = "- К оружию: на активном фронте кнопка открывает рог; щелчок по рогу отправляет рейдовое предупреждение всем союзникам вашей фракции с Overlord (раз в 4 часа на всю фракцию).\n- Управление: лидер группы или рейда становится Генералом фракции, его видно на карте, мини-карте и по табличке над головой; о его гибели узнают все.",
    GUIDE_SECTION_ALERTS = "Оповещения",
    GUIDE_ALERTS_BODY = "- Немезида: у пяти лучших вражеских бойцов недели над головой череп, а чат предупреждает, когда один из них появляется рядом (включается и выключается в настройках). Ваш смертельный удар по одному из них приносит +10 платины (раз в полчаса за каждого).\n- Вражеский разгром: вражеская гильдия быстро набирает ПП (/ov guildkills on или off).\n- Союзный разгром, зелёным: то же делает гильдия вашей фракции (/ov guildkills allies on или off).\n- Оповещения о захватах, аванпостах и рудниках приходят из зоны, где вы находитесь: «Оповещения о захватах» в настройках расширяет их до вашего континента или всего мира. О крепостях и аванпостах вашей гильдии, разгромах, призывах «К оружию» и полных победах вы узнаёте всегда. О крепостях и аванпостах других гильдий не сообщается, если не отмечено «Оповещения о крепостях и аванпостах других гильдий».\n- Крупные сражения: строка в чате, когда бой достигает 50 и более убийств за 5 минут, в любой точке мира («Оповещения о крупных сражениях» в настройках).",
    GUIDE_SECTION_GROUPS = "PvP-группы",
    GUIDE_GROUPS_BODY = "- PvP-группы (кнопка панели или /ov groups): опубликуйте свою группу с целью, местом, размером и минимальным уровнем или подайте заявку в одну из групп списка.\n- Объявления видят игроки вашей фракции с Overlord. Лидер приглашает вас автоматически или после одобрения заявки; приглашение игры вы принимаете сами.\n- Вступать в группу можно раз в 2 минуты. В подземельях отключено.",
    GUIDE_SECTION_TOOLS = "Рейтинг и Зал славы",
    GUIDE_TOOLS_BODY = "- Недельный рейтинг (/ov lb): ПП, гильдии с числом участников в рейтинге (щелчок по гильдии покажет их всех), очки гильдий (ПП и захваты; щелчок по «ПП» или «Очки» сортирует гильдии), крепости и аванпосты, поиск, оставшееся время и ваше место; в шапке, между итогами и вашим местом, зелёная стрелка, пока приходят данные рейтинга, затем зелёная галочка, когда он актуален.\n- /ov sync запрашивает данные у доступных игроков.\n- Зал славы (кнопка на панели): чемпионы прошлой недели, ваши подвиги и те, кто поддержал проект.",
    GUIDE_SECTION_RANKS = "Ранг Overlord",
    GUIDE_RANKS_BODY = "- Новая вкладка в окне персонажа (эмблема Overlord): пятнадцать рангов; полученный ранг не снижается.\n- Ранги с 1 по 10 открываются за славу: учитывается каждая почётная победа в открытом мире, а захват даёт больше. Учитывается только то, что Overlord видит с этого момента.\n- Для рангов с 11 по 14 также нужны три недели, завершённые в топ-100, 25, 10 и затем 3 недельного рейтинга вашей фракции; для последнего, Overlord, нужно больше славы и пять недель, завершённых на первом месте во фракции (в каждой — не менее 1 000 почётных побед). Недели суммируются и не обязаны идти подряд; более удачная неделя засчитывается и для более широких топов. Неделя засчитывается от 100 почётных побед, если вы играли в её последние 24 часа. Неделя в топ-3 или на первом месте требует ещё, чтобы ваш рейтинг был сверен с рейтингом других игроков за эти 24 часа.\n- Ваш ранг хранится только на этом компьютере, для этого персонажа, и нигде больше нет его копии: если данные аддонов игры удалены или потеряны (игра переустановлена, заменён диск, другой компьютер), ранг начинается с нуля и не может быть восстановлен.\n- Начиная с 11-го ранга другие игроки видят его значок рядом с вашим именем — в рейтинге и на индикаторах имён, — как только их собственный клиент его проверит: игроки вашей фракции — по данным игры и своим еженедельным рейтингам (после встреч с вами в разные недели), игроки другой фракции — по своим еженедельным рейтингам. Игрок, пропустивший ваши лучшие недели, может увидеть его позже или не увидеть вовсе.\n- Каждый полученный ранг объявляется на экране и появляется в Зале славы, в разделе «Ваши подвиги».",
    -- 2.1.1: /ov guild.
    HELP_GUILD_LANE = "|cFFFFFF00/ov guild [on || off]|r: сетевые сообщения в вашей гильдии, когда игра отклоняет канал аддона или в нём никто не отвечает",
    GUILD_LANE_ON = "Сетевые сообщения в гильдии, когда канал аддона отклонён или молчит: включены (/ov guild off, чтобы отключить).",
    REPORT_WINDOW_TITLE = "Overlord: отчёт о сети",
    REPORT_SELECT_ALL = "Выделить всё (затем Ctrl+C)",
    GUILD_LANE_OFF = "Сетевые сообщения в гильдии, когда канал аддона отклонён или молчит: отключены (/ov guild on, чтобы включить). Сообщения соратников по-прежнему читаются."
},
pt = {
    GUIDE_BTN_TOOLTIP = "Guia Forever (3 páginas)",
    GUIDE_PAGE1_TITLE = "Primeiros passos", GUIDE_PAGE2_TITLE = "Capturas e recursos",
    GUIDE_PAGE3_TITLE = "Fortalezas, postos e classificação",
    GUIDE_SECTION_TRAVEL = "Mundo aberto",
    GUIDE_TRAVEL_ALLIANCE = "- Vá a uma frente do Overlord no mundo aberto.\n- O mapa mostra os pontos que você pode capturar; o Próximo objetivo do painel indica o caminho.\n- No mapa do mundo, um grande brasão sobre cada continente mostra a facção que domina mais frentes nele.",
    GUIDE_SECTION_RULES = "Antes de capturar",
    GUIDE_RULES_BODY = "- Ative o JxJ (/pvp) e fique a pé dentro do círculo.\n- A captura para se você estiver montado, voando, em forma de viagem, em um veículo ou táxi, furtivo ou morto.\n- Se entrar voando em um círculo, você desmonta após um breve aviso.",
    GUIDE_SECTION_PROGRESS = "As sete frentes",
    GUIDE_PROGRESS_BODY = "- Planalto Arathi, Loch Modan, Durotar, Vale Gris, Floresta de Elwynn, Montanhas Cristarrubra e Contraforte de Eira dos Montes: uma rota de captura entre duas capitais.\n- Um ponto abre quando os anteriores são seus; vários ramos podem estar abertos ao mesmo tempo. Pontos abertos aparecem em amarelo com espadas cruzadas.\n- As vitórias honrosas (VH) no mundo aberto contam uma vez em qualquer nível, pelo contador oficial da Blizzard.",
    GUIDE_SECTION_SHARD = "Layers e sincronização",
    GUIDE_SHARD_BODY = "- Capturas e classificação são compartilhadas com todos os jogadores do seu tipo de reino (JxJ, Normal, RP, RP-JxJ ou Hardcore): canal do addon, guilda, grupo e amigos da Battle.net.\n- Se o jogo recusar o canal do addon ou ninguém responder nele, os dados passam pela sua guilda (/ov guild off para desligar). O Overlord também troca dados, por sussurros invisíveis, com alguns jogadores da lista de membros do canal, de qualquer guilda: capturas, cercos, combates (Atividade recente) e massacres de guilda passam de mão em mão em poucos segundos, mapas e classificação continuam passando de uma guilda para outra, mesmo sem guilda. Os jogadores encontrados assim são reencontrados depois, mesmo quando o jogo esconde a lista de membros.\n- A classificação se completa sozinha em segundo plano, mesmo com a janela fechada.\n- O ponto no cabeçalho do painel mostra o estado da rede, verde enquanto o canal, sua lista de membros ou sua guilda transportar seus dados (canal recusado incluído); /ov network dá os detalhes.\n- Um layer é a sua cópia do mundo aberto: forme grupo para lutar ao lado de aliados de outro layer.\n- Layers: clique no botão Layers do painel, ou no número do layer no canto superior esquerdo, para listar os jogadores que o Overlord ouve e seus layers. Entrar pede um convite a um voluntário daquele layer; você sai do grupo sozinho após a troca. Apenas voluntários: “Ajudar os outros” vem desativado por padrão. Os voluntários têm um ícone de portal na lista e são consultados primeiro; uma recusa diz o motivo.",
    GUIDE_SECTION_PANEL = "Painel do Overlord",
    GUIDE_PANEL_BODY = "- Botão do minimapa ou /ov show (/ov sozinho lista os comandos).\n- Escolha uma frente: seus pontos, a captura em andamento, os combates recentes e a barra de dominação semanal (passe o mouse: vitórias de frente da semana).\n- Botões: Grupos JxJ, Chamado às armas, Comando, a classificação e o Hall da Fama.\n- Sua platina, Ataque e Reforçar ficam no cartão Próximo objetivo.\n- Reabra este guia pelo painel ou com /ov guide.",
    GUIDE_SECTION_OPTIONS = "Configurações e comandos",
    GUIDE_OPTIONS_BODY = "- No painel, ou Esc → Opções → AddOns → Overlord.\n- Marcador do objetivo, mapa-múndi, Ícones do minimapa, sons, escala do painel, painel flutuante, Nêmesis e alertas de guilda.\n- Comandos úteis: /ov lb (classificação), /ov map (mapa-múndi: completo, compacto, só círculos ou oculto, também pelo botão do Overlord no canto do mapa: clique direito + arrastar o move, /ov map button o oculta), /ov sync (sincronizar), /ov guildkills.",
    GUIDE_SECTION_CONTEST = "Captura e disputa",
    GUIDE_CONTEST_BODY = "- Círculo comum: fique 2 minutos; ao sair, o progresso volta.\n- Inimigos em número igual ou maior o fazem recuar, mais rápido quanto maior a vantagem deles.\n- Capital inimiga: 8 minutos. Retomar a sua: 2 minutos.\n- Um ponto existe em cada layer: um atacante em outro layer não pode ser visto nem impedido a partir do seu. O chat avisa; entre no layer dele para lutar.\n- Uma captura espera, em pausa, enquanto um ponto de que ela precisa é atacado depois do seu início.\n- Um só temporizador por ponto: se vários de vocês estiverem nele, vale a captura que começou primeiro e as outras a seguem. Se quem captura sair do ponto ou morrer, um membro do grupo presente no ponto continua a captura.",
    GUIDE_SECTION_SIEGE = "Vitória na capital",
    GUIDE_SIEGE_BODY = "- Quando todos os outros pontos da frente forem seus, ataque a capital inimiga.\n- Tomá-la vence a frente: +1% de dominação semanal e 15 minutos de trégua.\n- Após a trégua, a conquista fica, incluindo a capital caída, até que a facção dela a retome (uma facção sempre pode atacar a própria capital).\n- Uma nova vitória na mesma frente só conta 6 horas depois da anterior.",
    GUIDE_SIEGE_BODY_NOTRUCE = "- Quando todos os outros pontos da frente forem seus, ataque a capital inimiga.\n- Tomá-la vence a frente: +1% de dominação semanal.\n- A conquista fica, incluindo a capital caída, até que a facção dela a retome (uma facção sempre pode atacar a própria capital).\n- Uma nova vitória na mesma frente só conta 6 horas depois da anterior.",
    GUIDE_SECTION_GOLD = "Minas de platina",
    GUIDE_GOLD_BODY = "Minas no mapa:\n%s\n\n- No círculo de uma mina, com o PvP ativo (/pvp): 1 de platina a cada 3 segundos (limite pessoal 100); minerar uma jazida dá 5.\n- Ataque, 25 de platina: sua próxima captura dura 60 segundos a menos (exceto capitais).\n- Reforçar, 25 de platina: a próxima captura inimiga de um dos seus pontos dura 60 segundos a mais (exceto capitais).\n- O estoque compartilhado se recompõe com o tempo.",
    GUIDE_SECTION_FEATURED = "Frente do dia e reinício semanal",
    GUIDE_FEATURED_BODY = "- A frente do dia muda todos os dias à meia-noite, no horário do seu computador.\n- Cada VH oficial nela dá +1 de platina.\n- A classificação, a dominação e o mapa de guerra reiniciam toda semana, no horário da sua região (Américas: terça-feira, Europa: quarta-feira, Coreia e Taiwan: quinta-feira de manhã).",
    GUIDE_SECTION_GUILD_KEEP = "Fortalezas de guilda",
    GUIDE_GUILD_KEEP_BODY = "Cinco fortalezas: Serra das Torres de Pedra, Pantanal, Ermos, Sertões e Mulgore.\n%s\n\n- Abertas a qualquer hora: um membro da guilda segura o quadrado por %d minutos.\n- Sair reduz o progresso; inimigos em número igual o congelam, em maioria o fazem recuar.\n- Só a facção adversária pode disputar ou tomar.\n- Ela fica com sua guilda até uma captura inimiga ou o reinício semanal; a tabela de fortalezas da classificação conta as capturas e sua dica mostra quem a tomou.\n- O ícone de pergaminho no cabeçalho de postos avançados da classificação mostra os conquistadores e as rivalidades entre guildas da semana.",
    GUIDE_SECTION_OUTPOST = "Postos avançados de guilda",
    GUIDE_OUTPOST_BODY = "- Um por frente, mais a Capela Savix (Floresta de Pinhaprata), o Pavilhão de Aeythyr (Terras Pestilentas Orientais), a Caverna do Urso de Lesi (Costa Negra) e o Poço Lunar de Anad'Ora (Feralas).\n- Regras das fortalezas, mas 5 minutos.\n- Enquanto uma guilda da sua facção tiver o posto de uma frente, o inimigo precisa de 30 segundos a mais nos pontos comuns dessa frente.",
    GUIDE_SECTION_FACTION_CALL = "Chamado às armas e General",
    GUIDE_FACTION_CALL_BODY = "- Chamado às armas: em uma frente ativa, o botão abre uma buzina; um clique na buzina envia um aviso de raide a todos os aliados Overlord da sua facção (uma vez a cada 4 horas para toda a facção).\n- Comando: um líder de grupo ou raide vira o General da sua facção, visível no mapa, no minimapa e na placa de nome; todos são avisados quando ele cai.",
    GUIDE_SECTION_ALERTS = "Alertas",
    GUIDE_ALERTS_BODY = "- Nêmesis: os cinco melhores matadores inimigos da semana têm uma caveira na placa de nome, e o chat avisa quando um deles aparece (liga ou desliga nas opções). Seu golpe final em um deles rende +10 de platina (uma vez por jogador a cada meia hora).\n- Massacre inimigo: uma guilda inimiga acumula VH em pouco tempo (/ov guildkills on ou off).\n- Massacre aliado, em verde: uma guilda da sua facção faz o mesmo (/ov guildkills allies on ou off).\n- Os alertas de captura, de postos avançados e de minas vêm da zona em que você está: \"Alertas de captura\" nas opções os estende ao seu continente ou ao mundo inteiro. As fortalezas e postos avançados da sua guilda, os massacres, os chamados às armas e as vitórias totais sempre chegam até você. Fortalezas e postos de outras guildas ficam em silêncio, a menos que você marque \"Alertas de fortalezas e postos de outras guildas\".\n- Grandes batalhas: uma linha no chat quando um combate chega a 50 abates ou mais em 5 minutos, em qualquer lugar do mundo (\"Alertas de grande batalha\" nas opções).",
    GUIDE_SECTION_GROUPS = "Grupos JxJ",
    GUIDE_GROUPS_BODY = "- Grupos JxJ (botão do painel ou /ov groups): publique seu grupo com objetivo, local, tamanho e nível mínimo, ou inscreva-se em um da lista.\n- Os anúncios chegam aos jogadores de Overlord da sua facção. O líder convida você, automaticamente ou após aprovar o pedido; o convite do jogo é você quem aceita.\n- Você pode entrar em um grupo a cada 2 minutos. Desligado em instâncias.",
    GUIDE_SECTION_TOOLS = "Classificação e Hall da Fama",
    GUIDE_TOOLS_BODY = "- Classificação semanal (/ov lb): VH, guildas com seus membros classificados (um clique numa guilda mostra todos), pontos das guildas (VH e capturas; um clique em VH ou Pontos ordena as guildas), fortalezas e postos, busca, tempo restante e sua posição; no cabeçalho, entre os totais e sua posição, uma seta verde enquanto os dados da classificação chegam e depois um visto verde quando ela está em dia.\n- /ov sync pede dados aos jogadores alcançáveis.\n- Hall da Fama (botão do painel): campeões da semana passada, seus feitos e os doadores.",
    GUIDE_SECTION_RANKS = "Patente Overlord",
    GUIDE_RANKS_BODY = "- Uma nova aba na sua ficha de personagem (logotipo do Overlord): quinze patentes; uma patente conquistada não cai.\n- As patentes 1 a 10 são pagas com Glória: cada vitória honrosa no mundo aberto conta, e uma captura conta mais. Só conta o que o Overlord vê a partir de agora.\n- As patentes 11 a 14 pedem também três semanas terminadas no top 100, 25, 10 e depois 3 da classificação semanal da sua facção; a última, Overlord, pede mais Glória e cinco semanas terminadas em primeiro da sua facção (com pelo menos 1.000 vitórias honrosas em cada uma). As semanas se somam e não precisam ser seguidas; uma semana melhor conta também para os tops mais amplos. Uma semana conta a partir de 100 vitórias honrosas, se você jogou durante as suas últimas 24 horas. Uma semana no top 3 ou terminada em primeiro exige também que a sua classificação tenha sido comparada com a de outros jogadores durante essas 24 horas.\n- Sua patente fica salva apenas neste computador, para este personagem, sem nenhuma cópia em outro lugar: se os dados de addons do jogo forem apagados ou perdidos (jogo reinstalado, disco trocado, outro computador), a patente volta a zero e não pode ser recuperada.\n- A partir da patente 11, os outros jogadores veem a insígnia dela ao lado do seu nome, na classificação e nas placas de nome, assim que o próprio cliente deles a verifica: os da sua facção com os dados do jogo e as próprias classificações semanais (depois que cruzam com você em semanas diferentes), os da outra facção com as próprias classificações semanais. Um jogador que perdeu suas melhores semanas pode vê-la mais tarde, ou nunca.\n- Cada patente alcançada é anunciada na tela e aparece no Hall da Fama, em Seus feitos.",
    -- 2.1.1: /ov guild.
    HELP_GUILD_LANE = "|cFFFFFF00/ov guild [on || off]|r: mensagens de rede na sua guilda quando o jogo recusa o canal do addon ou ninguém responde nele",
    GUILD_LANE_ON = "Mensagens de rede na guilda quando o canal do addon é recusado ou fica mudo: ativadas (/ov guild off para desligar).",
    REPORT_WINDOW_TITLE = "Overlord: relatório de rede",
    REPORT_SELECT_ALL = "Selecionar tudo (depois Ctrl+C)",
    GUILD_LANE_OFF = "Mensagens de rede na guilda quando o canal do addon é recusado ou fica mudo: desligadas (/ov guild on para religar). As dos seus colegas continuam sendo lidas."
},
zhCN = {
    GUIDE_BTN_TOOLTIP = "Forever 指南（3 页）",
    GUIDE_PAGE1_TITLE = "入门", GUIDE_PAGE2_TITLE = "占领与资源",
    GUIDE_PAGE3_TITLE = "公会要塞、前哨与排行",
    GUIDE_SECTION_TRAVEL = "前往开放世界",
    GUIDE_TRAVEL_ALLIANCE = "- 前往开放世界中的 Overlord 战线。\n- 地图显示可占领的据点；面板中的“下一个目标”为你指路。\n- 在世界地图上，每块大陆上方的大型徽记显示在该大陆统治战线最多的阵营。",
    GUIDE_SECTION_RULES = "占领之前",
    GUIDE_RULES_BODY = "- 开启 PvP（/pvp），并徒步站在占领圈内。\n- 骑乘、飞行、旅行形态、载具或飞行路线中、潜行或死亡时，占领会暂停。\n- 飞入占领圈时，短暂警告后会自动下坐骑。",
    GUIDE_SECTION_PROGRESS = "七条战线",
    GUIDE_PROGRESS_BODY = "- 阿拉希高地、洛克莫丹、杜隆塔尔、灰谷、艾尔文森林、赤脊山和希尔斯布莱德丘陵：每条战线都有连接双方首都的占领路线。\n- 之前的据点都归你后，下一个据点才会开放；多条分支可同时开放。开放的据点显示为黄色交叉双剑。\n- 任何等级在开放世界获得的荣誉击杀都按暴雪官方计数器只计一次。",
    GUIDE_SECTION_SHARD = "Layer 与同步",
    GUIDE_SHARD_BODY = "- 占领与排行数据与同类型服务器（PvP、普通、RP、RP-PvP 或 Hardcore）的所有玩家共享：插件频道、公会、队伍和 Battle.net 好友。\n- 如果游戏拒绝插件频道或频道中无人响应，数据会改由公会传输（/ov guild off 可关闭）。Overlord 还会以不可见的密语与频道成员列表中的几名玩家交换数据，不论其公会：占领、围攻、战斗（最近的活动）与公会大杀四方的消息会在几秒内逐人传递，即使没有公会，地图和排行仍能在公会之间传递。以这种方式遇到的玩家之后仍能再次找到，即使游戏隐藏了成员列表。\n- 排行榜会在后台自动补全，即使窗口关闭也一样。\n- 面板标题栏中的圆点显示网络状态，只要频道、频道成员列表或你的公会仍在传输你的数据（包括频道被拒时）就保持绿色；/ov network 查看详情。\n- Layer 是你所在开放世界的一个分层：与另一个 layer 上的盟友组队即可并肩作战。\n- Layer：点击面板上的“Layer 列表”按钮或左上角的 layer 编号，可列出 Overlord 听到的玩家及其 layer。“加入”会向该 layer 上的一名志愿者请求组队邀请；切换完成后你会自动离队。仅限志愿者：“帮助他人”默认关闭。志愿者在列表中带有传送门图标，并会被优先请求；被拒绝时会说明原因。",
    GUIDE_SECTION_PANEL = "Overlord 面板",
    GUIDE_PANEL_BODY = "- 小地图按钮或 /ov show（只输入 /ov 会列出所有命令）。\n- 选择战线：据点、当前占领、近期战斗和每周统治条（鼠标悬停：本周战线胜利）。\n- 按钮：PvP 队伍、战斗号召、命令、排行榜和名人堂。\n- 你的白金、进攻和加固位于“下一个目标”卡片中。\n- 可从面板或输入 /ov guide 重开本指南。",
    GUIDE_SECTION_OPTIONS = "设置与命令",
    GUIDE_OPTIONS_BODY = "- 在面板中，或 Esc → 选项 → AddOns → Overlord。\n- 目标标记、世界地图、小地图图标、音效、面板缩放、浮动面板、死敌和公会警报。\n- 常用命令：/ov lb（排行榜）、/ov map（世界地图：完整、紧凑、仅圆圈或隐藏，也可用地图角落的 Overlord 按钮；按住右键拖动可移动，/ov map button 可隐藏）、/ov sync（同步）、/ov guildkills。",
    GUIDE_SECTION_CONTEST = "占领与争夺",
    GUIDE_CONTEST_BODY = "- 普通占领圈：停留 2 分钟；离开后进度会回落。\n- 圈内敌人与你人数相同或更多时进度会倒退，敌人越多倒退越快。\n- 敌方首都：8 分钟。夺回己方首都：2 分钟。\n- 每个位面都有同一个据点：在另一个位面的攻击者，你在自己的位面既看不到也无法阻止。聊天栏会提示；进入对方的位面才能交战。\n- 占领所需的据点在占领开始后遭到攻击时，占领会暂停等待。\n- 每个据点只有一个计时器：多人同时站在上面时，以最先开始的占领为准，其他人跟随它。如果占领者离开据点或死亡，站在据点上的队友会继续占领。",
    GUIDE_SECTION_SIEGE = "首都胜利",
    GUIDE_SIEGE_BODY = "- 当战线上其他据点都归你后，进攻敌方首都。\n- 占领它即可赢得战线：+1% 每周统治值，并开启 15 分钟停战。\n- 停战结束后，征服成果保留，陷落的首都也不例外，直到其阵营夺回（阵营随时可以进攻自己的首都）。\n- 同一战线的新胜利要在上一次胜利 6 小时后才会计入。",
    GUIDE_SIEGE_BODY_NOTRUCE = "- 当战线上其他据点都归你后，进攻敌方首都。\n- 占领它即可赢得战线：+1% 每周统治值。\n- 征服成果保留，陷落的首都也不例外，直到其阵营夺回（阵营随时可以进攻自己的首都）。\n- 同一战线的新胜利要在上一次胜利 6 小时后才会计入。",
    GUIDE_SECTION_GOLD = "白金矿区",
    GUIDE_GOLD_BODY = "地图上的矿区：\n%s\n\n- 在矿区圈内（需开启PvP，/pvp）：每 3 秒 1 点白金（个人上限 100）；开采一处矿脉获得 5。\n- 进攻，25 点白金：你的下次占领缩短 60 秒（首都除外）。\n- 加固，25 点白金：敌人下次占领你的据点延长 60 秒（首都除外）。\n- 共享矿区储量会逐渐恢复。",
    GUIDE_SECTION_FEATURED = "每日战线与每周重置",
    GUIDE_FEATURED_BODY = "- 每日战线每天在你电脑的本地时间午夜轮换。\n- 在该战线的每次官方击杀奖励 +1 点白金。\n- 排行榜、统治值和战争地图每周按你所在地区的时间重置（美洲：周二，欧洲：周三，韩国和台湾：周四上午）。",
    GUIDE_SECTION_GUILD_KEEP = "公会要塞",
    GUIDE_GUILD_KEEP_BODY = "五座公会要塞：石爪山脉、湿地、荒芜之地、贫瘠之地和莫高雷。\n%s\n\n- 随时开放：公会成员守住方形区域 %d 分钟即可占领。\n- 离开会损失进度；敌我人数相同时进度暂停，敌人更多时倒退。\n- 只有敌对阵营能争夺或占领。\n- 要塞由其公会持有，直到被敌人占领或每周重置；排行榜的要塞表统计占领次数，鼠标提示显示占领者。\n- 排行榜前哨表头的卷轴图标会显示本周的占领者和公会宿敌。",
    GUIDE_SECTION_OUTPOST = "公会前哨",
    GUIDE_OUTPOST_BODY = "- 每条战线各一处，另有银松森林的 Savix 教堂、东瘟疫之地的 Aeythyr 小屋、黑海岸的“Lesi 的熊洞”和菲拉斯的“Anad'Ora 月亮井”。\n- 遵循要塞规则，但只需 5 分钟。\n- 你阵营的公会持有某条战线的前哨时，敌人占领该战线普通据点需要多 30 秒。",
    GUIDE_SECTION_FACTION_CALL = "战斗号召与将军",
    GUIDE_FACTION_CALL_BODY = "- 战斗号召：在活跃战线上，按钮会打开一只号角；点击号角即可向你阵营中所有安装 Overlord 的盟友发送团队警告（整个阵营每 4 小时一次）。\n- 命令：队伍或团队领袖成为本阵营的将军，显示在地图、小地图和姓名板上；将军阵亡时所有人都会收到通知。",
    GUIDE_SECTION_ALERTS = "警报",
    GUIDE_ALERTS_BODY = "- 死敌：本周击杀最多的五名敌人姓名板上显示骷髅，其中一人出现时聊天框会提醒你（可在选项中开启或关闭）。对其中一人完成最后一击可获得 +10 白金（每名玩家每半小时一次）。\n- 敌方屠戮：敌方公会在短时间内大量击杀（/ov guildkills on 或 off）。\n- 友方屠戮，绿色显示：本阵营公会大杀四方（/ov guildkills allies on 或 off）。\n- 占领、前哨站和矿洞警报来自你所在的区域：选项中的“占领警报”可将其扩展到你所在的大陆或全世界。你公会的要塞和前哨站、屠戮、战斗号召和全面胜利始终会通知你。其他公会的要塞和前哨不会通报，除非勾选“其他公会的要塞和前哨警报”。\n- 大型战斗：当一场战斗在5分钟内达到50次或更多击杀时，在聊天框显示一行，范围为全世界（选项中的“大型战斗警报”）。",
